def is_valid_range_string(s):
    parts = s.split('-')
    if len(parts) != 2:
        return False
    a, b = parts
    for p in (a, b):
        if not p.isdigit():
            return False
        if len(p) > 1 and p[0] == '0':
            return False
    return int(a) <= int(b)

def is_valid_port_range(s):
    parts = s.split('-')
    if len(parts) != 2:
        return False
    a, b = parts
    for p in (a, b):
        if not p.isdigit():
            return False
        if len(p) > 1 and p[0] == '0':
            return False
        if int(p) > 65535:
            return False
    return int(a) <= int(b)

def is_valid_weighted_checksum_ascending_mod11(s):
    if len(s) < 2:
        return False
    body, check = s[:-1], s[-1]
    if not body.isdigit():
        return False
    total = sum((i + 1) * int(d) for i, d in enumerate(body))
    rem = total % 11
    expected = 'X' if rem == 10 else str(rem)
    return check == expected

def is_valid_weighted_checksum_alternating_sign(s):
    if len(s) < 2:
        return False
    body, check_c = s[:-1], s[-1]
    if not body.isdigit() or not check_c.isdigit():
        return False
    total = sum((1 if i % 2 == 0 else -1) * int(d) for i, d in enumerate(body))
    return int(check_c) == total % 10

def is_valid_parity_bit_string(s):
    if len(s) < 2 or any(c not in '01' for c in s):
        return False
    return s.count('1') % 2 == 0

def is_valid_pin_code(s):
    if len(s) != 4 or not s.isdigit():
        return False
    digits = [int(c) for c in s]
    if len(set(digits)) == 1:
        return False
    if all(digits[i] + 1 == digits[i + 1] for i in range(3)):
        return False
    if all(digits[i] - 1 == digits[i + 1] for i in range(3)):
        return False
    return True

def is_valid_coupon_code(s):
    if len(s) != 8 or not all(c.isalnum() and (c.isdigit() or c.isupper()) for c in s):
        return False
    has_letter = any(c.isalpha() for c in s)
    has_digit = any(c.isdigit() for c in s)
    return has_letter and has_digit

def is_valid_flight_number(s):
    import re
    return bool(re.fullmatch(r'[A-Z]{2}\d{3,4}', s))

